//! Hash algorithm constants — GENERATED by `ggen sync run` from the
//! `strata-hash-pack` ontology. Do not edit by hand.
//!
//! Source of truth is the RDF ontology; regenerate rather than patching.
//! Ground truth for lengths: BLAKE3 default 256-bit (32-byte) output
//! (BLAKE3 paper, 2020); SHA-256 32-byte digest (FIPS 180-4 §6.2).

/// Number of hash algorithms projected from the ontology.
pub const HASH_ALGO_COUNT: usize = 2;

/// (name, digest length in bytes) per supported algorithm, ordered by name.
pub const HASH_ALGOS: [(&str, usize); HASH_ALGO_COUNT] = [


    ("BLAKE3", 32),

    ("SHA_256", 32),

];

#[cfg(test)]
mod tests {
    use super::*;

    /// Court: the family digest width is 32 bytes for every projected
    /// algorithm (BLAKE3 default output; FIPS 180-4 §6.2).
    #[test]
    fn all_digests_are_32_bytes() {
        assert!(HASH_ALGO_COUNT >= 2);
        for (name, len) in HASH_ALGOS {
            assert_eq!(len, 32, "{name} must output 32 bytes");
        }
    }

    /// Court: the algorithm set closes over exactly {BLAKE3, SHA_256}
    /// (mirror of gates/020_algorithm_closure.rq).
    #[test]
    fn algorithm_closure() {
        let names: Vec<&str> = HASH_ALGOS.iter().map(|&(n, _)| n).collect();
        assert_eq!(names, vec!["BLAKE3", "SHA_256"]);
    }
}
